package com.example.proyectolp.repository;
import com.example.proyectolp.model.XpEntry; import com.example.proyectolp.service.SupabaseService; import java.util.*;
public class XpLogRepository {private final SupabaseService db;public XpLogRepository(SupabaseService d){db=d;}public List<XpEntry> list()throws Exception{List<XpEntry> all=new ArrayList<>();int offset=0;while(true){List<XpEntry> page=db.getList("xp_log?select=*&order=created_at,id&limit=1000&offset="+offset,XpEntry.class);all.addAll(page);if(page.size()<1000)return all;offset+=1000;}}public int total()throws Exception{return list().stream().mapToInt(e->e.amount).sum();}public boolean add(int amount,String reason,String key)throws Exception{return !db.insertIgnore("xp_log?on_conflict=user_id,dedupe_key",Map.of("amount",amount,"reason",reason,"dedupe_key",key),XpEntry.class).isEmpty();}}
